data = read('/input/data')
rows = data['rows']
ordered = sorted([[row['start'], row['end']] for row in rows], key=lambda x: x[0])
segments = []
for interval in ordered:
    if len(segments) == 0:
        segments = segments + [[interval[0], interval[1]]]
    else:
        last = segments[len(segments) - 1]
        if interval[0] <= last[1]:
            if interval[1] > last[1]:
                segments[len(segments) - 1] = [last[0], interval[1]]
        else:
            segments = segments + [[interval[0], interval[1]]]
covered = sum([segment[1] - segment[0] for segment in segments])
result = {'main': {'segments': segments, 'covered': covered}}
